be permanecer dentro del alcance del conjuro. Cuando finaliza el conjuro, el objetivo flota suavemente hasta el suelo si aún sigue en el aire. Aclaración de reglas 2014: Un objeto objetivo debe estar suelto.","higherLevels":"","range":"60 pies","components":"","material":"","ritual":false,"duration":"Concentración, hasta 10 minutos","concentration":true,"castingTime":"1 acción","school":"Transmutación","classes":["sorcerer","wizard"],"attackType":"none","saveAbility":"","damageExpression":"","upcastDamageExpression":"","addAbilityModifier":false,"damageType":"","year":"2014","catalog":{"contentKey":"official:spell:es:2014:levitate","origin":"official","tags":["manual_jugador"],"revision":0}},"casting":{"source":"inventory:inv_02aa25a497c8692d327129ee30be1c44:doss-levitate","ability":"charisma","kind":"item","key":"levitate","level":2,"traitId":null},"effect":{"description":"","active":false}}$doss_aefc576cbe612994$::jsonb,0,statement_timestamp(),'bfb475fe-b9a3-4362-9cf7-fc419491a405'::uuid);if exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-spell' and parent_id='chr_345a4e8763475f1c2acbd5c2a56bcf36' and entity_id='spl_6ded588188559142acde7b5c9b05f9a2')then raise exception 'DOSS_SPELL_EXISTS';end if;insert into public.campaign_state_fragments(campaign_id,fragment_kind,parent_id,entity_id,position,payload,revision,updated_at,updated_by)values('9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd','character-spell','chr_345a4e8763475f1c2acbd5c2a56bcf36','spl_6ded588188559142acde7b5c9b05f9a2',22,$doss_5b1d39fefbf9bc38${"id":"spl_6ded588188559142acde7b5c9b05f9a2","order":10004,"name":"Protección contra la energía","level":3,"prepared":true,"definition":{"name":"Protección contra la energía","level":3,"description":"Mientras dure el conjuro, la criatura voluntaria que toques tiene resistencia a un tipo de daño de tu elección: ácido, frio, fuego, electtricidad o sonico.","higherLevels":"","range":"T