no puede ser encantado, asustado o poseído por ellos. Si el objetivo ya se encuentra encantado, asustado o poseído por tal criatura, el objetivo tendrá ventaja en cualquier tirada de salvación en contra del efecto relevante.","higherLevels":"","range":"Toque","components":"","material":"","ritual":false,"duration":"Concentración, hasta 10 minutos","concentration":true,"castingTime":"1 acción","school":"Abjuración","classes":["cleric","paladin","warlock","wizard"],"attackType":"none","saveAbility":"","damageExpression":"","upcastDamageExpression":"","addAbilityModifier":false,"damageType":"","year":"2014","catalog":{"contentKey":"official:spell:es:2014:protection-from-evil-and-good","origin":"official","tags":["manual_jugador"],"revision":0}},"casting":{"source":"inventory:inv_02aa25a497c8692d327129ee30be1c44:doss-protection-from-evil-and-good","ability":"charisma","kind":"item","key":"protection-from-evil-and-good","level":1,"traitId":null},"effect":{"description":"","active":false}}$doss_df06eec70d59504e$::jsonb,0,statement_timestamp(),'bfb475fe-b9a3-4362-9cf7-fc419491a405'::uuid);if exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-spell' and parent_id='chr_345a4e8763475f1c2acbd5c2a56bcf36' and entity_id='spl_4388a7a7912638696291b8f17fd8fa18')then raise exception 'DOSS_SPELL_EXISTS';end if;insert into public.campaign_state_fragments(campaign_id,fragment_kind,parent_id,entity_id,position,payload,revision,updated_at,updated_by)values('9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd','character-spell','chr_345a4e8763475f1c2acbd5c2a56bcf36','spl_4388a7a7912638696291b8f17fd8fa18',24,$doss_2c4ef382b523f281${"id":"spl_4388a7a7912638696291b8f17fd8fa18","order":10006,"name":"Protección contra el veneno","level":2,"prepared":true,"definition":{"name":"Protección contra el veneno","level":2,"description":"Tocas una criatura. Si esta envenenada, neutralizas el veneno. Si más de un veneno aflige al objetivo, neutralizarás un veneno que sepas que está presente, o neutralizarás uno al azar. Mientras dure el conjuro, el objetivo tiene ventaja en las tiradas de salvación en contra de ser envenenado, y tendrá resistencia al daño por veneno.","higherLevels":"","range":"Toque","components":"","material":"","ritual":false,"duration":"1 hora","concentration":false,"castingTime":"1 acción","school":"Abjuración","classes":["cleric","druid","paladin","ranger"],"attackType":"none","saveAbility":"","damageExpression":"","upcastDamageExpression":"","addAbilityModifier":false,"damageType":"","year":"2014","catalog":{"contentKey":"official:spell:es:2014:protection-from-poison","origin":"official","tags":["manual_jugador"],"revision":0}},"casting":{"source":"inventory:inv_02aa25a497c8692d327129ee30be1c44:doss-protection-from-poison","ability":"charisma","kind":"item","key":"protection-from-poison","level":2,"traitId":null},"effect":{"description":"","active":false}}$doss_2c4ef382b523f281$::jsonb,0,statement_timestamp(),'bfb475fe-b9a3-4362-9cf7-fc419491a405'::uuid);if not exists(select 1 from public.campaign_character_versions where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and character_id='chr_345a4e8763475f1c2acbd5c2a56bcf36' and revision=17)then raise exception 'DOSS_CHARACTER_CHANGED';end if;update public.campaign_character_versions set revision=revision+1,updated_at=statement_timestamp()where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and character_id='chr_345a4e8763475f1c2acbd5c2a56bcf36';update public.campaigns set state_revision=state_revision+1,state_updated_at=statement_timestamp(),updated_at=statement_timestamp()where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd';end $doss$;select(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')as revision,1 as copies,7 as spells;commit;